def _score(slug, text):
    return 0  # placeholder replaced below

def map_tool(name, desc):
    text = (" " + name + " " + (desc or "") + " ").lower().replace("-", " ").replace("_", " ")
    best, best_score = None, 0
    for slug, prefix, kws in DBS:
        score = 0
        for kw in kws:
            if kw in text:
                score += 3 if " " in kw else 1
        if score > best_score:
            best, best_score = slug, score
    return best

TOOL_DBS = {slug: (slug, prefix) for slug, prefix, kws in DBS}

if __name__ == "__main__":
    tests = ["Wi-Fi Ambient Power Harvester", "Air-Gapped Optical Diode", "Wireshark",
             "Docker Engine", "Godot Engine", "Low Battery Lock-In", "Places I've Pooped",
             "SurrealDB", "PCB Trace Autorouter", "SAT Solver Engine", "Bloom Filter Utility"]
    for t in tests:
        print(t, "->", map_tool(t, t))
